        const isWinner = idx === 0;
        const mapsUrl = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(p.posto + ' ' + p.endereco + ' ' + p.cidade)}`;
        
        let termoAmazonCombustivel = 'aditivo combustivel limpa bicos';
